import itertools
# Helper to run cascade on a given modified grid (with an extra edge if provided)
def simulate_with_added_edge(edge=None):
    # Start from the global G, copy and possibly add an edge (line upgrade)
    Gm = G.copy()
    if edge is not None:
        a,b = edge
        if not Gm.has_edge(a,b):
            Gm.add_edge(a,b)
    # Step 1: Compute initial loads on the intact (modified) network
    L0 = nx.betweenness_centrality(Gm, normalized=False)
    # Step 2: Capacities = (1+alpha) * initial_load
    alpha = 0.2
    cap = {n: (1+alpha) * L0.get(n, 0.0) for n in Gm.nodes()}
    # Step 3: Trigger: remove line 48-68 if present
    if Gm.has_edge(48,68):
        Gcur = Gm.copy()
        Gcur.remove_edge(48,68)
    else:
        Gcur = Gm.copy()
    # Step 4: Cascading rounds
    round_num = 0
    while True:
        round_num += 1
        if Gcur.number_of_nodes() == 0:
            break
        L = nx.betweenness_centrality(Gcur, normalized=False)
        overloaded = [n for n in Gcur.nodes() if L.get(n,0.0) > cap.get(n, 0.0)]
        if not overloaded:
            break
        Gcur.remove_nodes_from(overloaded)
    # Step 5: After cascade, surviving network is the largest connected component
    if Gcur.number_of_nodes() == 0:
        survivors = 0
    else:
        lcc = max(nx.connected_components(Gcur), key=len)
        survivors = len(lcc)
    return survivors, Gcur, edge

# Candidates
candidates = [(31,81), (23,76), (48,82)]

results = {}
for cand in candidates:
    surv, G_final, edge_used = simulate_with_added_edge(cand)
    results[cand] = {"survivors": surv, "final_nodes": G_final.number_of_nodes()}

# Also test with no upgrade (baseline) for comparison
baseline_surv, _, _ = simulate_with_added_edge(None)
results[("baseline", "none")] = {"survivors": baseline_surv, "final_nodes": None}

print("Results per candidate (survivors in largest connected component after cascade):")
for key, val in results.items():
    print(f"{key}: survivors={val['survivors']}, final_nodes={val['final_nodes']}")
